import re

def get_images(path):
    images = []
    for filename in listdir(path):
        if re.match(r'^[a-z0-9_-]+\.jpg$', filename, re.IGNORECASE):
            images.append(filename)
    return images

from urllib.parse import urlparse

def is_valid_url(url):
